  var strength=b.trees.stream().filter(t->t.skill()==Skill.strength).findFirst().orElseThrow().nodes();var vengeance=strength.stream().filter(n->n.ability().endsWith("/vengeance")).findFirst().orElseThrow();var forbidden=strength.stream().filter(n->n.ability().endsWith("/forbidden_strength")).findFirst().orElseThrow();var adrenaline=strength.stream().filter(n->n.ability().endsWith("/adrenaline_fiend")).findFirst().orElseThrow();check(vengeance.y()==3&&forbidden.y()==6&&adrenaline.x()==forbidden.x()&&adrenaline.y()>forbidden.y(),"shifted strength chain and adrenaline");
